/// SessionDeadline (gh-1556): the ONE wall-clock budget source for a run —
/// the temporal sibling of the FinalizeGate (gh-1412).
///
/// A host, a CLI flag, or a mid-session `/timer` command arms a single
/// epoch-ms deadline on this clock; every consumer (the per-turn
/// `time-left:` request line, the one-shot wrap-up steering notices, the
/// TUI countdown chip, the `FA_DEADLINE_EPOCH_MS` bash env var) projects
/// THE SAME value. Later setters override earlier ones (env < flag <
/// `/timer`); the TUI chip is a pure projection, never a second timer.
///
/// Contract (the ticket's binding threats):
/// - Never lie about the clock: the deadline comes ONLY from the host env
///   or an explicit user set; fa never invents or extends it.
/// - Missing/invalid env = feature OFF, silent — no errors, no prompts.
/// - An explicit user set with an invalid spec is a CLEAR user-facing
///   error ([FormatException]) — never a silently wrong deadline.
/// - Not a procrastination loop: each ladder crossing fires ONCE per
///   arming (a re-set/adjust re-arms the latch set).
/// - The guillotine stays the host's: notices are steerings the model may
///   ignore.
///
/// Pure Dart: the wall clock is injected (defaulting to [DateTime.now]);
/// no `dart:io` anywhere.
library;

/// Env var a host exports to hand the session its deadline (epoch ms).
/// Injected into bash tool executions live per exec through the
/// session-correlation env seam (see `SessionVarsExecutionEnv`), so a
/// mid-session `/timer` adjustment is picked up by the next command.
const String deadlineEpochMsEnvVar = 'FA_DEADLINE_EPOCH_MS';

/// A bare-integer spec at or above this value is read as an epoch-ms
/// timestamp (1973-09-09 onward); anything smaller is rejected as an
/// ambiguous duration missing its unit — silently reading `90` as 90 ms
/// would be a lying clock.
const int deadlineEpochMsFloor = 100000000000;

/// One crossing of the default notice ladder.
enum DeadlineNoticeKind {
  /// ~50% of the budget elapsed: start converging.
  halfBudget,

  /// T-3min (the load-bearing steer): stop exploring, finalize outputs,
  /// drain/kill background shell jobs, run checks.
  wrapUp,

  /// T-30s: write the final answer NOW.
  finalAnswer,
}

/// A one-shot steering notice produced by [SessionDeadline.pollNotices].
final class DeadlineNotice {
  /// Creates a notice.
  const DeadlineNotice(this.kind, this.text);

  /// Which ladder crossing fired.
  final DeadlineNoticeKind kind;

  /// The model-facing steering text (already rendered with the current
  /// remaining budget).
  final String text;

  @override
  String toString() => 'DeadlineNotice(${kind.name})';
}

/// The default notice ladder: the crossing thresholds plus the steering
/// texts. Injectable so tests can compress the windows without waiting.
final class DeadlineLadder {
  /// Creates a ladder. [wrapUpSteerMs] defaults to T-3min, [finalAnswerMs]
  /// to T-30s.
  const DeadlineLadder({
    this.wrapUpSteerMs = 3 * 60 * 1000,
    this.finalAnswerMs = 30 * 1000,
  });

  /// The wrap-up steer fires when the remaining budget drops to this many
  /// ms (default 3 min).
  final int wrapUpSteerMs;

/// The FinalizeGate contract + TaskLedger (gh-1412): near-miss elimination
/// for unattended runs.
///
/// An unattended agent must stop declaring success on intent and start
/// declaring it on re-verified state. Two named components:
///
/// - **FinalizeGate** — the prompt contract (unattended/bench mode only;
///   `prompts/cli/finalize_gate.md`, rendered by the hosts into the system
///   prompt). Before any final summary the agent re-quotes every explicit
///   requirement as a checklist, verifies each item with a real command
///   against the produced state, and fixes every unmet item. A final
///   answer that still carries unmet items is budget-conditional (gh-1646):
///   compliant only when the wall clock is effectively reached or every
///   unmet item names a blocker the agent cannot change — an honest
///   ledger is not an early-exit license. Step 2.5 (gh-1652) re-runs each
///   produced entry point the way the grader will — neutral cwd, fresh
///   subprocess, clean env — so the ledger's oracle is the verifier's
///   own invocation, not the agent's checklist.
/// - **TaskLedger** — the checklist itself as a hidden session record
///   (`task_ledger` custom record, shaped like `model_request_summary`):
///   post-mortems see WHAT was self-checked, the bench summary reports
///   near-miss proximity (items verified / checks passed), and CI can
///   REG-gate the contract's presence.
///
/// The loop parses the `task-ledger` block out of the run's final
/// assistant message ([parseTaskLedger], tolerant to the unfenced
/// near-miss shape models emit — gh-1516), rewrites the answer so the
/// transcript never shows the ledger ([stripTaskLedger]), and emits
/// [TaskLedgerEvent]
/// (declared in `agent_loop.dart` — the event family is sealed there);
/// hosts persist [taskLedgerRecordType] records and the trajectory
/// snapshot builder folds them.
library;

/// The `custom` record type of the TaskLedger session record.
const String taskLedgerRecordType = 'task_ledger';

/// The fenced-block info string the FinalizeGate contract mandates for the
/// final answer's ledger (`​```task-ledger … `​`` `).
const String taskLedgerFence = 'task-ledger';

/// Per-item verification outcome. `fixed` = failed, then fixed and
/// re-verified — counts as verified (the fix loop is the contract's point).
enum TaskLedgerItemStatus {
  pass,
  fail,
  fixed;

  /// The payload spelling.
  String get jsonName => name;

  /// Tolerant parse: a missing or unrecognized status is [fail] — an
  /// unverified item must never silently count as verified.
  static TaskLedgerItemStatus fromName(Object? name) {
    final token = '[REDACTED:Sensitive Value]'.trim().toLowerCase().split(RegExp(r'\s')).first;
    if (token.startsWith('pass')) return pass;
    if (token.startsWith('fix')) return fixed;
    return fail;
  }
}

