    expect(finalizeGateContractPrompt, contains('NO tool calls at all'));
    expect(
      finalizeGateContractPrompt,
      isNot(contains('state-changing commands')),
    );
  });

  test('gh-1646 C2: "report" is no longer an alternative to "fix" — the '
