import io, json, os
raw = json.load(io.open('input/pr-1654/pr_discussions_raw.json', encoding='utf-8'))
replies = []
for t in raw['threads']:
    tid = t.get('threadId')
    if not tid:
        continue
    replies.append({
        'inReplyToId': t['rootCommentId'],
        'threadId': tid,
        'reply': 'outputs/review_replies/thread_%d.md' % t['index'],
    })
assert len(replies) == 5, len(replies)
io.open('outputs/review_replies.json', 'w', encoding='utf-8').write(
    json.dumps({'replies': replies}, ensure_ascii=False, indent=2) + '\n')
out = json.load(io.open('outputs/review_replies.json', encoding='utf-8'))
src = {t['threadId']: t['rootCommentId'] for t in raw['threads'] if t.get('threadId')}
for r in out['replies']:
    assert src[r['threadId']] == r['inReplyToId']
    assert os.path.isfile(r['reply']), r['reply']
print('review_replies.json regenerated + verified:', len(out['replies']), 'replies')
PYEOF"}

